    patches = []
    for r in range(h):
        for c in range(w):
            if seen[r][c] or grid[r][c] in (bg, wall):
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            colors = Counter()
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                colors[grid[y][x]] += 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                        not seen[yy][xx] and grid[yy][xx] not in (bg, wall)):
                        seen[yy][xx] = True
                        q.append((yy, xx))
            patches.append((colors.most_common(1)[0][0], cells))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != wall:
                continue
            best_dist, best_color = h + w, wall
